#include <iostream>
using std::cin;
using std::cout;
using std::cerr;
using std::endl;

int main (void) {
	int a, b;
	cin >> a >> b;

	if ((double)a > (double)b * 2 / 3) {
		cout << "Yes" << "\n";
	} else {
		cout << "No" << "\n";
	}

	return 0;
}

